export const responseStream = (response) => response.stream.pipe(Stream.mapError((error) => httpError({ error, request: response.request, operation: "read", http: responseHttp(response) })));
export const responseBytes = (response) => response.arrayBuffer.pipe(Effect.map((buffer) => new Uint8Array(buffer)), Effect.mapError((error) => httpError({ error, request: response.request, operation: "read", http: responseHttp(response) })));
export const responseText = (response) => response.text.pipe(Effect.mapError((error) => httpError({ error, request: response.request, operation: "read", http: responseHttp(response) })));
